// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance == false || true);
        amount = bound(amount, 1, type(uint128).max);
        Reverter r = new Reverter();
        vm.deal(address(c), amount);
        vm.prank(address(this));
        bool ok;
        try c.sendTo(address(r), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "sendTo to a rejecting receiver must revert");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
